// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.ruleimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.skill.SystemOperationimport kotlin.reflect.KClass/** * NOUS — Brain rule contract. * * A rule is a declarative mapping: WHEN [condition] THEN [action]. * Rules are deterministic, side-effect-free during evaluation (actions * execute only when rule fires), and priority-ordered. * * Three sources of rules (per spec §5.1): *   1. Compiled rules — annotated with [Rule], registered via Hilt multibinding *   2. User rules — stored in Room `user_rules` table (NL automation creates these) *   3. Imported rules — JSON files in `files/rules/` (one-time import to Room) * * @see <a href="docs/spec/module2-spec-review.pdf">§5 Layer 1</a> */interface BrainRule {    /** Unique rule ID (e.g., "torch_on_rule", "night_mode_rule"). */    val id: String    /** Lower number = higher priority. Conflicts resolved by priority. */    val priority: Int    /** When this rule should fire. */    val condition: RuleCondition    /** What to do when condition matches. */    val action: RuleAction    /** Tags for grouping (e.g., "system", "communication", "ambient"). */    val tags: Set<String>    /** Whether this rule is currently enabled (user can disable). */    val isEnabled: Boolean        get() = true    /** Human-readable description (shown in Settings → Automation). */    val description: String        get() = "Rule $id"}/** * Rule conditions — when a rule should fire. * * Composable: AND, OR, NOT. Context-aware: matches on brain state (time, * location, battery). */sealed interface RuleCondition {    /** Matches if intent is exactly this type. */    data class IntentIs(val intent: KClass<out Intent>) : RuleCondition    /** Matches if intent matches a predicate. */    data class IntentMatches(val predicate: (Intent) -> Boolean) : RuleCondition    /** Combines conditions with AND — all must match. */    data class And(val conditions: List<RuleCondition>) : RuleCondition    /** Combines conditions with OR — any must match. */    data class Or(val conditions: List<RuleCondition>) : RuleCondition    /** Negates a condition. */    data class Not(val condition: RuleCondition) : RuleCondition    /** Matches if context (time, location, battery) satisfies predicate. */    data class Context(val predicate: (BrainContext) -> Boolean) : RuleCondition    /** Always matches — useful for catch-all rules. */    data object Always : RuleCondition}/** * Rule actions — what to do when condition matches. */sealed interface RuleAction {    /** Trigger a system operation (torch, volume, brightness, etc.). */    data class SystemCall(val operation: SystemOperation) : RuleAction    /** Invoke a skill with parameters. */    data class SkillInvoke(val skillId: String, val params: Map<String, String>) : RuleAction    /** Execute multiple actions in sequence. */    data class Composite(val actions: List<RuleAction>) : RuleAction    /** Explicitly defer to next layer (don't fire, hand off). */    data class DeferToLayer(val layer: Int) : RuleAction    /** Return a response message directly (no action needed). */    data class Respond(val message: String) : RuleAction}/** * Result of evaluating a rule against an intent + context. */sealed interface RuleEvaluation {    /** Rule matched and should fire. */    data class Matched(val rule: BrainRule) : RuleEvaluation    /** Rule did not match. */    data object NotMatched : RuleEvaluation    /** Rule is disabled. */    data class Disabled(val rule: BrainRule) : RuleEvaluation    /** Rule evaluation threw an error. */    data class Error(val rule: BrainRule, val throwable: Throwable) : RuleEvaluation}